mapper.select:
SELECT COALESCE(SUM(amount), 0)
FROM growth_point_ledger
WHERE student_id = #{studentId}
  AND change_type IN ('TASK_REWARD', 'CORRECTION')
  AND occurred_at >= #{startAt}
  AND occurred_at < #{endExclusive}

SELECT COUNT(*)
FROM learn_task_pause pause_record
INNER JOIN learn_task_assignment assignment
    ON assignment.id = pause_record.assignment_id
WHERE assignment.student_id = #{studentId}
  AND pause_record.started_at >= #{startAt}
  AND pause_record.started_at < #{endExclusive}
